import { MakeLogicType, actions, kea, path, reducers, selectors } from 'kea'

import {
    DEFAULT_SQL_EDITOR_LAYOUT,
    SqlEditorInspectorSide,
    SqlEditorInspectorTab,
    SqlEditorLayout,
    SqlEditorResultsPlacement,
    moveInspectorTab,
    normalizeSqlEditorLayout,
    openInspectorTab,
    setInspectorTabVisible,
} from './sqlEditorLayout'

export type SqlEditorPanelSizes = Record<string, number>

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface sqlEditorLayoutLogicValues {
    editorSizes: SqlEditorPanelSizes | null
    inspectorOverlayOpen: boolean
    isCustomized: boolean
    layout: SqlEditorLayout
    storedLayout: SqlEditorLayout
    workspaceSizes: SqlEditorPanelSizes | null
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface sqlEditorLayoutLogicActions {
    moveInspectorTab: (
        tab: SqlEditorInspectorTab,
        toIndex: number
    ) => {
        tab: SqlEditorInspectorTab
        toIndex: number
    }
    resetLayout: () => {
        value: true
    }
    setEditorSizes: (sizes: SqlEditorPanelSizes) => {
        sizes: SqlEditorPanelSizes
    }
    setInspectorOpen: (open: boolean) => {
        open: boolean
    }
    setInspectorOverlayOpen: (open: boolean) => {
        open: boolean
    }
    setInspectorSide: (side: SqlEditorInspectorSide) => {
        side: SqlEditorInspectorSide
    }
    setInspectorTab: (tab: SqlEditorInspectorTab) => {
        tab: SqlEditorInspectorTab
    }
    setInspectorTabVisible: (
        tab: SqlEditorInspectorTab,
        visible: boolean
    ) => {
        tab: SqlEditorInspectorTab
        visible: boolean
    }
    setResultsPlacement: (placement: SqlEditorResultsPlacement) => {
        placement: SqlEditorResultsPlacement
    }
    setWorkspaceSizes: (sizes: SqlEditorPanelSizes) => {
        sizes: SqlEditorPanelSizes
    }
    toggleInspector: () => {
        value: true
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface sqlEditorLayoutLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        layout: (storedLayout: SqlEditorLayout) => SqlEditorLayout
        isCustomized: (layout: SqlEditorLayout) => boolean
    }
}

export type sqlEditorLayoutLogicType = MakeLogicType<
    sqlEditorLayoutLogicValues,
    sqlEditorLayoutLogicActions,
    Record<string, any>,
    sqlEditorLayoutLogicMeta
>

export const sqlEditorLayoutLogic = kea<sqlEditorLayoutLogicType>([
    // pinned: the path is the localStorage key prefix for the persisted reducers below; renaming it
    // resets everyone's layout
    path(['products', 'data_warehouse', 'frontend', 'sql_editor', 'workspace', 'sqlEditorLayoutLogic']),
    actions({
        setInspectorOpen: (open: boolean) => ({ open }),
        toggleInspector: true,
        setInspectorOverlayOpen: (open: boolean) => ({ open }),
        setInspectorTab: (tab: SqlEditorInspectorTab) => ({ tab }),
        setInspectorTabVisible: (tab: SqlEditorInspectorTab, visible: boolean) => ({ tab, visible }),
        moveInspectorTab: (tab: SqlEditorInspectorTab, toIndex: number) => ({ tab, toIndex }),
        setInspectorSide: (side: SqlEditorInspectorSide) => ({ side }),
        setResultsPlacement: (placement: SqlEditorResultsPlacement) => ({ placement }),
        setWorkspaceSizes: (sizes: SqlEditorPanelSizes) => ({ sizes }),
        setEditorSizes: (sizes: SqlEditorPanelSizes) => ({ sizes }),
        resetLayout: true,
    }),
    reducers({
        storedLayout: [
            DEFAULT_SQL_EDITOR_LAYOUT as SqlEditorLayout,
            { persist: true },
            {
                setInspectorOpen: (state, { open }) => {
                    const layout = normalizeSqlEditorLayout(state)
                    return { ...layout, inspector: { ...layout.inspector, open } }
                },
                toggleInspector: (state) => {
                    const layout = normalizeSqlEditorLayout(state)
                    return { ...layout, inspector: { ...layout.inspector, open: !layout.inspector.open } }
                },
                setInspectorTab: (state, { tab }) => openInspectorTab(normalizeSqlEditorLayout(state), tab),
                setInspectorTabVisible: (state, { tab, visible }) =>
                    setInspectorTabVisible(normalizeSqlEditorLayout(state), tab, visible),
                moveInspectorTab: (state, { tab, toIndex }) =>
                    moveInspectorTab(normalizeSqlEditorLayout(state), tab, toIndex),
                setInspectorSide: (state, { side }) => {
                    const layout = normalizeSqlEditorLayout(state)
                    return { ...layout, inspector: { ...layout.inspector, side } }
                },
                setResultsPlacement: (state, { placement }) => {
                    const layout = normalizeSqlEditorLayout(state)
                    return { ...layout, results: { placement } }
                },
                resetLayout: () => DEFAULT_SQL_EDITOR_LAYOUT,
            },
        ],
        workspaceSizes: [
            null as SqlEditorPanelSizes | null,
            { persist: true },
            {
                setWorkspaceSizes: (_, { sizes }) => sizes,
                // Sizes are keyed by panel id, and moving the inspector or the results changes which
                // panels share a group, so the old sizes no longer fit.
                setInspectorSide: () => null,
                resetLayout: () => null,
            },
        ],
        // When the workspace is too narrow to dock the side panel, it floats over the query instead.
        // That only happens on request, so this is kept apart from the docked panel's persisted state.
        inspectorOverlayOpen: [
            false,
            {
                setInspectorOverlayOpen: (_, { open }) => open,
                setInspectorTab: () => true,
            },
        ],
        editorSizes: [
            null as SqlEditorPanelSizes | null,
            { persist: true },
            {
                setEditorSizes: (_, { sizes }) => sizes,
                setResultsPlacement: () => null,
                resetLayout: () => null,
            },
        ],
    }),
    selectors({
        // Persisted state can come from an older version of this logic, so it is read through the
        // normalizer every time rather than trusted as is.
        layout: [
            (s) => [s.storedLayout],
            (storedLayout: sqlEditorLayoutLogicValues['storedLayout']): SqlEditorLayout =>
                normalizeSqlEditorLayout(storedLayout),
        ],
        isCustomized: [
            (s) => [s.layout],
            (layout: sqlEditorLayoutLogicValues['layout']): boolean =>
                layout.inspector.side !== DEFAULT_SQL_EDITOR_LAYOUT.inspector.side ||
                layout.results.placement !== DEFAULT_SQL_EDITOR_LAYOUT.results.placement ||
                layout.inspector.tabs.join() !== DEFAULT_SQL_EDITOR_LAYOUT.inspector.tabs.join(),
        ],
    }),
])
